# First, let's see what's happening with the sandbox - try a simple ping
import requests
import sys

BASE = "{{TESTVDB_DB_URL}}"
HEADERS = {"Content-Type": "application/json"}

try:
    resp = requests.get(f"{BASE}/v1/.well-known/ready", timeout=5)
    print(f"Ready: {resp.status_code}")
except Exception as e:
    print(f"Error: {e}")

try:
    resp = requests.get(f"{BASE}/v1/meta", timeout=5)
    print(f"Meta: {resp.status_code} {resp.text[:500]}")
except Exception as e:
    print(f"Meta error: {e}")

sys.exit(0)
